s = 0\\n\\n        async def loader(project):\\n            nonlocal calls\\n            calls += 1\\n            if calls == 1:\\n                first_started.set()\\n                await release_first.wait()\\n                return \\\"old A text\\\"\\n            return \\\"new A text\\\"\\n\\n        old = asyncio.create_task(state.open(\\\"A\\\", loader))\\n        await first_started.wait()\\n        await state.open(\\\"A\\\", loader)\\n        release_first.set()\\n        await old\\n\\n        self.assertEqual(state.project, \\\"A\\\")\\n        self.assertEqual(state.text, \\\"new A text\\\")\\n        self.assertFalse(state.loading)\\n        self.assertIsNone(state.error)\\n\\n    async def test_stale_failure_cannot_set_error_or_end_current_loading(self):\\n        state = DocumentController()\\n        old_started = asyncio.Event()\\n        fail_old = asyncio.Event()\\n        new_started = asyncio.Event()\\n        release_new = asyncio.Event()\\n\\n        async def loader(project):\\n            if project == \\\"A\\\":\\n                old_started.set()\\n                await fail_old.wait()\\n                raise RuntimeError(\\\"old failure\\\")\\n            new_started.set()\\n            await release_new.wait()\\n            return \\\"B text\\\"\\n\\n        old = asyncio.create_task(state.open(\\\"A\\\", loader))\\n        await old_started.wait()\\n        new = asyncio.create_task(state.open(\\\"B\\\", loader))\\n        await new_started.wait()\\n\\n        fail_old.set()\\n        await old\\n        self.assertTrue(state.loading)\\n        self.assertIsNone(state.error)\\n        self.assertEqual(state.text, \\\"\\\")\\n\\n        release_new.set()\\n        await new\\n        self.assertEqual((state.project, state.text), (\\\"B\\\", \\\"B text\\\"))\\n        self.assertFalse(state.loading)\\n        self.assertIsNone(state.error)\\n\\n    async def test_current_failure_preserves_user_edit(self):\\n        state = DocumentController()\\n        started = asyncio.Event()\\n        release = asyncio.Event()\\n\\n        async def loader(project):\\n            started.set()\\n            await release.wait()\\n            raise ValueError(\\\"cannot load\\\")\\n\\n        task = asyncio.create_task(state.open(\\\"A\\\", loader))\\n        await started.wait()\\n        state.edit(\\\"draft\\\")\\n        release.set()\\n        await task\\n\\n        self.assertEqual(state.text, \\\"draft\\\")\\n        self.assertEqual(state.error, \\\"cannot load\\\")\\n        self.assertFalse(state.loading)\\n\\n    async def test_close_invalidates_pending_success_and_failure(self):\\n        for should_fail in (False, True):\\n            with self.subTest(should_fail=should_fail):\\n                state = DocumentController()\\n                started = asyncio.Event()\\n                release = asyncio.Event()\\n\\n                async def loader(project):\\n                    started.set()\\n                    await release.wait()\\n                    if should_fail:\\n                        raise RuntimeError(\\\"late failure\\\")\\n                    return \\\"late text\\\"\\n\\n                task = asyncio.create_task(state.open(\\\"A\\\", loader))\\n                await started.wait()\\n                state.close()\\n                release.set()\\n                await task\\n\\n                self.assertEqual(\\n                    (state.project, state.text, state.loading, state.error),\\n                    (None, \\\"\\\", False, None),\\n                )\\n\\n    async def test_current_cancellation_propagates_and_ends_loading(self):\\n        state = DocumentController()\\n        started = asyncio.Event()\\n\\n        async def loader(project):\\n            started.set()\\n            await asyncio.Event().wait()\\n\\n        task = asyncio.create_task(state.open(\\\"A\\\", loader))\\n        await started.wait()\\n        task.cancel()\\n\\n        with self.assertRaises(asyncio.CancelledError):\\n            await task\\n        self.assertFalse(state.loading)\\n        self.assertIsNone(state.error)\\n\\n    async def test_stale_cancellation_does_not_end_latest_loading(self):\\n        state = DocumentController()\\n        old_started = asyncio.Event()\\n        new_started = asyncio.Event()\\n        release_new = asyncio.Event()\\n\\n        async def loader(project):\\n            if project == \\\"A\\\":\\n                old_started.set()\\n                await asyncio.Event().wait()\\n            new_started.set()\\n            await release_new.wait()\\n            return \\\"B text\\\"\\n\\n        old = asyncio.create_task(state.open(\\\"A\\\", loader))\\n        await old_started.wait()\\n        new = asyncio.create_task(state.open(\\\"B\\\", loader))\\n        await new_started.wait()\\n\\n        old.cancel()\\n        with self.assertRaises(asyncio.CancelledError):\\n            await old\\n        self.assertTrue(state.loading)\\n\\n        release_new.set()\\n        await new\\n        self.assertEqual(state.text, \\\"B text\\\")\\n        self.assertFalse(state.loading)\\n\"},\"done\":false,\"verification\":\"尚未执行本轮代码。已依据公开失败覆盖旧成功覆盖新请求与加载期间编辑，并补充A→A、过期错误/loading、失败保留编辑、close失效、当前及过期取消等回归场景；等待评测运行器返回原始测试结果。\"}"}}
