import asyncio


class AsyncMemo:
    def __init__(self):
        self._tasks = {}

    async def get(self, key, loader):
        task = self._tasks.get(key)
        if task is None:
            task = asyncio.create_task(loader())
            self._tasks[key] = task
            task.add_done_callback(
                lambda completed, cache_key=key: self._remove_unsuccessful(
                    cache_key, completed
                )
            )
        return await asyncio.shield(task)

    def _remove_unsuccessful(self, key, task):
