{"document.py": "class DocumentController:
    def __init__(self):
        self.project = None
        self.text = ""
        self.loading = False
        self.error = None

    async def open(self, project, loader):
        self.project = project
        self.text = ""
        self.loading = True
        self.error = None
        try:
            self.text = await loader(project)
        except Exception as exc:
            self.error = str(exc)
        finally:
            self.loading = False

    def edit(self, text):
        self.text = text

    def close(self):
        self.project = None
        self.text = ""
        self.loading = False
        self.error = None
", "README.md": "# 异步文档打开
Python 3.11+，仅标准库。DocumentController持有project/text/loading/error四个公开状态。open(project, loader)开始时选择项目，清空显示文字与错误并设置loading；loader接收project，异步返回文稿字符串。edit(text)记录用户当前输入，close()关闭当前项目并清空全部公开状态。
报告：A项目加载慢，切换到B后突然又显示A；加载时用户输入的文字也可能被覆盖。
契约：只有最新一次open请求可以提交结果、错误或结束loading，包括A→B→A重复选择同一项目的情况。等待期间的edit必须保留；当前请求成功或失败仍结束loading。当前请求失败时显示错误但保留已有用户编辑。close以后旧请求不能恢复内容或错误。取消open应向调用者传播CancelledError，仅当前请求的取消可结束loading。每次open开始清空文字的既有行为要保留。无需取消旧loader、增加网络请求、持久化或第三方依赖。
", "test_public.py": "import asyncio
import unittest
from document import DocumentController


class PublicDocumentTests(unittest.IsolatedAsyncioTestCase):
    async def test_normal_open(self):
        state = DocumentController()
        async def loader(project):
            return project + " text"
        await state.open("A", loader)
        self.assertEqual((state.project, state.text, state.loading, state.error), ("A", "A text", False, None))

    async def test_slow_previous_project_cannot_overwrite_new_project(self):
        state = DocumentController()
        started, release = asyncio.Event(), asyncio.Event()
        async def loader(project):
            if project == "A":
                started.set()
                await release.wait()
            return project + " text"
        old = asyncio.create_task(state.open("A", loader))
        await started.wait()
        await state.open("B", loader)
        release.set()
        await old
        self.assertEqual((state.project, state.text), ("B", "B text"))

    async def test_user_edit_during_load_is_kept(self):
        state = DocumentController()
        started, release = asyncio.Event(), asyncio.Event()
        async def loader(project):
            started.set()
            await release.wait()
            return "disk text"
        task = asyncio.create_task(state.open("A", loader))
        await started.wait()
        state.edit("typed text")
        release.set()
        await task
        self.assertEqual(state.text, "typed text")
        self.assertFalse(state.loading)
"}
