        async def loader(project):
            started.set()
            await release.wait()
            return "disk text"
        task = asyncio.create_task(state.open("A", loader))
        await started.wait()
        state.edit("typed text")
        release.set()
        await task
        self.assertEqual(state.text, "typed text")
        self.assertFalse(state.loading)
