import asyncio


class AsyncMemo:
    def __init__(self):
        self._tasks = {}

    async def get(self, key, loader):
        task = self._tasks.get(key)
        if task is None:
            task = asyncio.create_task(loader())
            self._tasks[key] = task
            task.add_done_callback(
                lambda completed, cached_key=key: self._discard_unsuccessful(
                    cached_key, completed
                )
            )

        try:
            return await asyncio.shield(task)
        finally:
            # This also makes cleanup visible before a caller that observed the
            # task's error immediately attempts the same key again.
            self._discard_unsuccessful(key, task)

    def _discard_unsuccessful(self, key, task):
        if not task.done():
            return

        unsuccessful = task.cancelled()
        if not unsuccessful:
            # Retrieving the exception also prevents an unobserved-exception
            # warning if every waiter was cancelled before the loader failed.
            unsuccessful = task.exception() is not None

        if unsuccessful and self._tasks.get(key) is task:
            self._tasks.pop(key, None)

    def invalidate(self, key):
        self._tasks.pop(key, None)

